package com.college.hospitalmanagement;
import jakarta.persistence.*;
@Entity @Table(name="beds",uniqueConstraints=@UniqueConstraint(name="uk_bed_room_number",columnNames={"room_id","bed_number"})) public class Bed{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="bed_number",nullable=false,length=30) private String bedNumber;@ManyToOne(optional=false) @JoinColumn(name="ward_id") private Ward ward;@ManyToOne(optional=false) @JoinColumn(name="room_id") private Room room;@Column(nullable=false,length=50) private String bedType;@Column(nullable=false,length=20) private String status;public Long getId(){return id;}public String getBedNumber(){return bedNumber;}public Ward getWard(){return ward;}public Room getRoom(){return room;}public String getBedType(){return bedType;}public String getStatus(){return status;}public void setBedNumber(String v){bedNumber=v;}public void setWard(Ward v){ward=v;}public void setRoom(Room v){room=v;}public void setBedType(String v){bedType=v;}public void setStatus(String v){status=v;}}
